int fm10k_init_module(void)
{
    int err;

    pr_info("FM10K driver version %s\n", FM10K_DRIVER_VERSION);
    pr_info("Copyright (c) 2021-2023 Intel Corporation\n");

    fm10k_wq = create_workqueue("fm10k_wq");
    if (!fm10k_wq)
        return -ENOMEM;

    err = fm10k_dbg_init();
    if (err)
        goto err_destroy_wq;

    err = pci_register_driver(&fm10k_pci_driver);
    if (err)
        goto err_dbg_exit;

    return 0;

err_dbg_exit:
    fm10k_dbg_exit();
err_destroy_wq:
    destroy_workqueue(fm10k_wq);
    return err;
}

